#!/bin/sh -e

# Check MPIRUN - if not set, warn but continue (MPI is optional for this test)
if [ -z "${MPIRUN}" ]; then
    echo "Warning: MPIRUN is not set. Running in serial mode."
    echo "For MPI testing, set MPIRUN (e.g., MPIRUN="mpirun -np 2")"
fi


mkdir -p lanczos_hubbard_square/
cd lanczos_hubbard_square

cat > stan.in <<EOF
W = 4
L = 2
model = "FermionHubbard"
method = "Lanczos"
lattice = "Tetragonal"
t = 1.0
U = 4.0
nelec = 8
2Sz = 0
outputmode = "all"
EOF

${MPIRUN} ../../src/HPhi -s stan.in

# Check value

cat > reference.dat <<EOF
  -10.2529529552637637
    1.0444442739280932
    0.0000000000000000
EOF
paste output/zvo_energy.dat reference.dat > paste1.dat
diff=`awk 'BEGIN{diff=0.0} {diff+=sqrt(($2-$3)*($2-$3))} END{printf "%8.6f", diff}' paste1.dat`

